public class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public ListNode insertNodeAtTail(ListNode head, int data) {
    ListNode newNode = new ListNode(data);
    if (head == null) {
        return newNode;
    }
    ListNode cur = head;
    while (cur.next != null) {
        cur = cur.next;
    }
    cur.next = newNode;
    return head;
}

code.python:
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def insertNodeAtTail(self, head: ListNode, data: int) -> ListNode:
    new_node = ListNode(data)
    if head is None:
        return new_node
    cur = head
    while cur.next is not None:
        cur = cur.next
    cur.next = new_node
    return head

